files.render.bx:
// Renders a BMX document with BMX's own implementation, in Burxt.
//
// Compiled into the image at provision, so a run is one process starting rather than a compile. The
// visitor's document arrives at /work/document.bmx and the rendered page goes to stdout; a refusal
// carries BMX's own code, which is the whole point of asking the format's implementation rather than a
// reimplementation of it.
use "bmx/burxt/bmx.bx";
use "std/files.bx";
use "std/os.bx";

let path: String = os_arg(1);
let mutable binds: [Binding] = [];
match bmx_to_html(file_read(path), binds) {
    Ok(html) => { print(html); }
    Error(why) => {
        print_error(why);
        exit(1);
    }
}
